"""(T)NPSE: Neural Posterior Score Estimation and Truncated Sequential NPSE.

Implementation follows Sharrock et al. (2024), Sections 2-3 and Appendix E.3.
"""
import math
import numpy as np
import torch
import torch.nn as nn
from scipy.integrate import solve_ivp


# ----------------------------------------------------------------------------- SDEs
class VESDE:
    def __init__(self, sigma_min, sigma_max):
        self.smin, self.smax = sigma_min, sigma_max
        self.eps = 0.0  # sigma_min > 0 so t=0 is fine

    def marginal(self, t):  # mean coefficient, std
        std = self.smin * (self.smax / self.smin) ** t
        return torch.ones_like(t), std

    def drift(self, th, t):
        return torch.zeros_like(th)

    def g2(self, t):
        std = self.smin * (self.smax / self.smin) ** t
        return std ** 2 * 2 * math.log(self.smax / self.smin)

    def prior_sample(self, n, d):
        return torch.randn(n, d) * self.smax

    def prior_logp(self, z):
        d = z.shape[1]
        return -0.5 * (z ** 2).sum(1) / self.smax ** 2 - d * math.log(self.smax) - 0.5 * d * math.log(2 * math.pi)


class VPSDE:
    def __init__(self, beta_min=0.1, beta_max=11.0):
        self.b0, self.b1 = beta_min, beta_max
        self.eps = 1e-3

    def int_beta(self, t):
        return self.b0 * t + 0.5 * (self.b1 - self.b0) * t ** 2

    def marginal(self, t):
        ib = self.int_beta(t)
        return torch.exp(-0.5 * ib), torch.sqrt(1 - torch.exp(-ib))

    def beta(self, t):
        return self.b0 + t * (self.b1 - self.b0)

    def drift(self, th, t):
        return -0.5 * self.beta(t) * th

    def g2(self, t):
        return self.beta(t)

    def prior_sample(self, n, d):
        return torch.randn(n, d)

    def prior_logp(self, z):
        d = z.shape[1]
        return -0.5 * (z ** 2).sum(1) - 0.5 * d * math.log(2 * math.pi)


# ----------------------------------------------------------------------------- network
def mlp(i, o, h=256):
    return nn.Sequential(nn.Linear(i, h), nn.SiLU(), nn.Linear(h, h), nn.SiLU(), nn.Linear(h, o))


class ScoreNet(nn.Module):
    """theta-embedding MLP + x-embedding MLP + sinusoidal t embedding -> MLP (App. E.3.2)."""

    def __init__(self, d, p, sde):
        super().__init__()
        self.sde = sde
        self.th_emb = mlp(d, max(30, 4 * d))
        self.x_emb = mlp(p, max(30, 4 * p))
        self.net = mlp(max(30, 4 * d) + max(30, 4 * p) + 64, d)
        i = torch.arange(32, dtype=torch.float32)
        self.register_buffer("freqs", 1.0 / 10000 ** (i / 31))

    def t_emb(self, t):
        a = t[:, None] * self.freqs[None]
        return torch.cat([torch.sin(a), torch.cos(a)], 1)

    def forward(self, th, x, t):
        h = torch.cat([self.th_emb(th), self.x_emb(x), self.t_emb(t)], 1)
        _, std = self.sde.marginal(t)
        return self.net(h) / std[:, None]  # output parametrised as score * std


def dsm_loss(net, sde, th0, x):
    n = th0.shape[0]
    t = torch.rand(n) * (1 - sde.eps) + sde.eps
    m, std = sde.marginal(t)
    z = torch.randn_like(th0)
    tht = m[:, None] * th0 + std[:, None] * z
    s = net(tht, x, t)
    # lambda_t = std^2 weighting: ||std * s + z||^2
    return ((std[:, None] * s + z) ** 2).sum(1).mean()


# ----------------------------------------------------------------------------- estimator
class NPSE:
    def __init__(self, sde_type, d, p, sigma_min=0.05, lr=1e-4, seed=0):
        self.sde_type, self.d, self.p, self.sigma_min, self.lr = sde_type, d, p, sigma_min, lr
        self.net = None
        torch.manual_seed(seed)

    def setup(self, theta, x):
        """Fix standardisation and sigma_max from (first-round) training data."""
        self.th_mu, self.th_sd = theta.mean(0), theta.std(0) + 1e-8
        self.x_mu, self.x_sd = x.mean(0), x.std(0) + 1e-8
        if self.sde_type == "ve":
            ths = self.zt(theta)
            sub = ths[torch.randperm(len(ths))[:5000]]
            smax = torch.cdist(sub, sub).max().item()  # Technique 1, Song & Ermon (2020)
            self.sde = VESDE(self.sigma_min, smax)
        else:
            self.sde = VPSDE()
        self.net = ScoreNet(self.d, self.p, self.sde)
        self.opt = torch.optim.Adam(self.net.parameters(), lr=self.lr)

    def zt(self, th):
        return (th - self.th_mu) / self.th_sd

    def zx(self, x):
        return (x - self.x_mu) / self.x_sd

    def train(self, theta, x, batch_size=50, max_iters=3000, patience=1000, val_every=10):
        th, xx = self.zt(theta), self.zx(x)
        n = len(th)
        perm = torch.randperm(n)
        nv = max(int(0.15 * n), 1)
        vi, ti = perm[:nv], perm[nv:]
        thv, xv, tht, xt = th[vi], xx[vi], th[ti], xx[ti]
        g = torch.Generator().manual_seed(1)
        best, best_state, since = float("inf"), None, 0
        for it in range(max_iters):
            idx = torch.randint(0, len(tht), (batch_size,))
            loss = dsm_loss(self.net, self.sde, tht[idx], xt[idx])
            self.opt.zero_grad()
            loss.backward()
            self.opt.step()
            if it % val_every == 0:
                with torch.no_grad():
                    st = torch.get_rng_state()
                    torch.manual_seed(1234)
                    vl = dsm_loss(self.net, self.sde, thv, xv).item()
                    torch.set_rng_state(st)
                if vl < best:
                    best, since = vl, 0
                    best_state = {k: v.clone() for k, v in self.net.state_dict().items()}
                else:
                    since += val_every
                if since >= patience:
                    break
        self.net.load_state_dict(best_state)
        return it + 1

    # ------------------------------------------------------------------ probability flow ODE
    def _v(self, th, xo, t):
        tt = torch.full((th.shape[0],), t)
        return self.sde.drift(th, tt) - 0.5 * self.sde.g2(tt)[:, None] * self.net(th, xo.expand(th.shape[0], -1), tt)

    def _v_div(self, th, xo, t):
        with torch.enable_grad():
            th = th.detach().requires_grad_(True)
            v = self._v(th, xo, t)
            div = torch.zeros(th.shape[0])
            for i in range(self.d):
                div = div + torch.autograd.grad(v[:, i].sum(), th, retain_graph=i < self.d - 1)[0][:, i]
        return v.detach(), div.detach()

    @torch.no_grad()
    def sample(self, x_obs, n, rtol=1e-4, atol=1e-4, chunk=20000):
        out = []
        xo = self.zx(x_obs.reshape(1, -1))
        for c in range(0, n, chunk):
            m = min(chunk, n - c)
            z = self.sde.prior_sample(m, self.d)

            def f(t, y):
                th = torch.from_numpy(y).float().reshape(m, self.d)
                return self._v(th, xo, t).numpy().ravel().astype(np.float64)

            sol = solve_ivp(f, (1.0, self.sde.eps), z.numpy().ravel().astype(np.float64), method="RK45", rtol=rtol, atol=atol)
            out.append(torch.from_numpy(sol.y[:, -1]).float().reshape(m, self.d))
        th = torch.cat(out)
        return th * self.th_sd + self.th_mu

    def _logp_std(self, ths, xo, rtol=1e-4, atol=1e-4):
        """log density in standardised space via instantaneous change of variables (eq. 5)."""
        m = ths.shape[0]

        def f(t, y):
            th = torch.from_numpy(y[: m * self.d]).float().reshape(m, self.d)
            v, div = self._v_div(th, xo, t)
            return np.concatenate([v.numpy().ravel(), div.numpy()]).astype(np.float64)

        y0 = np.concatenate([ths.numpy().ravel(), np.zeros(m)]).astype(np.float64)
        sol = solve_ivp(f, (self.sde.eps, 1.0), y0, method="RK45", rtol=rtol, atol=atol)
        yT = sol.y[:, -1]
        zT = torch.from_numpy(yT[: m * self.d]).float().reshape(m, self.d)
        intdiv = torch.from_numpy(yT[m * self.d:]).float()
        return self.sde.prior_logp(zT) + intdiv

    def log_prob(self, theta, x_obs, chunk=10000):
        xo = self.zx(x_obs.reshape(1, -1))
        ths = self.zt(theta)
        out = [self._logp_std(ths[c:c + chunk], xo) for c in range(0, len(ths), chunk)]
        return torch.cat(out) - torch.log(self.th_sd).sum()


# ----------------------------------------------------------------------------- algorithms
def run_npse(task, sde_type, num_sims, observations, num_samples=10000, seed=0, sigma_min=0.05):
    torch.manual_seed(seed)
    prior, sim = task.get_prior(), task.get_simulator()
    theta = prior(num_samples=num_sims)
    x = sim(theta)
    est = NPSE(sde_type, theta.shape[1], x.shape[1], sigma_min=sigma_min, seed=seed)
    est.setup(theta, x)
    bs = 500 if num_sims >= 100000 else 50
    iters = est.train(theta, x, batch_size=bs)
    samples = {o: est.sample(task.get_observation(o)[0], num_samples) for o in observations}
    return samples, iters


def run_tsnpse(task, sde_type, num_sims, obs_idx, num_samples=10000, num_rounds=10, seed=0, sigma_min=0.05,
               n_hpr=20000, eps=5e-4, log=print):
    """Truncated sequential NPSE (Algorithm 1)."""
    torch.manual_seed(seed)
    prior, sim = task.get_prior(), task.get_simulator()
    x_obs = task.get_observation(obs_idx)[0]
    M = num_sims // num_rounds
    bs = 500 if num_sims >= 100000 else 200
    D_th, D_x = [], []
    est, kappa, box = None, None, None
    accept_hist = []
    for r in range(num_rounds):
        if r == 0:
            th = prior(num_samples=M)
        else:
            th = sample_truncated(est, prior, x_obs, M, kappa, box)
        x = sim(th)
        D_th.append(th); D_x.append(x)
        if r == 0:
            est = NPSE(sde_type, th.shape[1], x.shape[1], sigma_min=sigma_min, seed=seed)
            est.setup(th, x)  # sigma_max uses first-round data only (addendum)
        Th, X = torch.cat(D_th), torch.cat(D_x)
        est.train(Th, X, batch_size=bs)
        if r < num_rounds - 1:
            ps = est.sample(x_obs, n_hpr)
            ps = ps[torch.isfinite(prior.log_prob(ps))] if torch.isfinite(prior.log_prob(ps)).any() else ps
            lp = est.log_prob(ps, x_obs)
            kappa = torch.quantile(lp[torch.isfinite(lp)], eps).item()
            box = (ps.min(0).values, ps.max(0).values)
            log(f"  round {r+1}: |D|={len(Th)} kappa={kappa:.3f}")
    return est.sample(x_obs, num_samples)


def sample_truncated(est, prior, x_obs, M, kappa, box, batch=5000, max_tries=200):
    acc, n_eval = [], 0
    for _ in range(max_tries):
        cand = prior(num_samples=batch)
        inbox = ((cand >= box[0]) & (cand <= box[1])).all(1)  # cheap hypercube pre-rejection
        cand = cand[inbox]
        if len(cand) > 0:
            lp = est.log_prob(cand, x_obs)
            n_eval += len(cand)
            acc.append(cand[lp > kappa])
        if sum(len(a) for a in acc) >= M:
            break
    acc = torch.cat(acc) if acc else torch.zeros(0, est.d)
    if len(acc) < M:  # fallback (should be rare): fill with prior samples inside box
        extra = []
        while sum(len(e) for e in extra) < M - len(acc):
            c = prior(num_samples=batch); extra.append(c[((c >= box[0]) & (c <= box[1])).all(1)])
        acc = torch.cat([acc] + extra)
    return acc[torch.randperm(len(acc))[:M]]

